 manual(12,2,7,.75,f'برای مقدارهای مجاز، [(x²−{a*a})/(x+1)]×[(x+1)/(x−{a})] را ساده و محدودیت‌ها را بنویس.',f'x+{a}؛ x≠−1 و x≠{a}',[('تجزیهٔ صورت',.25),('حذف عامل‌ها و پاسخ',.25),('حفظ هر دو مقدار ممنوع',.25)],expr=f'(x**2-{a*a})/(x+1)*(x+1)/(x-{a})')
 manual(12,3,7,.75,f'طول و عرض مستطیل به‌ترتیب x/(x−{a}) و {k}/(x−{a}) است؛ x>{a}. محیط را بر حسب x ساده کن.',f'2(x+{k})/(x−{a})',[('فرمول دو برابر مجموع طول و عرض',.25),('جمع کسرهای هم‌مخرج',.25),('پاسخ ساده و توجه به دامنه',.25)],expr=f'2*(x/(x-{a})+{k}/(x-{a}))')
