 manual(13,1,7,1.25,f'تقسیم x²{signed_term(C-a,"x")}{signed_term(R-a*C)} بر x−{a} را انجام بده؛ خارج‌قسمت و باقی‌مانده و رابطهٔ کنترل را بنویس.',f'خارج‌قسمت x+{C}؛ باقی‌مانده {R}؛ مقسوم=(x−{a})(x+{C})+{R}',[('نخستین جملهٔ خارج‌قسمت',.25),('ضرب و تفریق مرحلهٔ نخست',.25),('جملهٔ دوم و ادامهٔ تقسیم',.25),('باقی‌ماندهٔ درست',.25),('رابطهٔ درستی تقسیم',.25)],expr=f'rem(x**2+{C-a}*x+({R-a*C}),x-{a},x)')
 manual(14,1,8,1,f'برای روکش یک توپ با قطر {2*r} سانتی‌متر، بدون اتلاف یا هم‌پوشانی چند سانتی‌متر مربع ماده لازم است؟ پاسخ را بر حسب π بنویس.',f'{4*r*r}π سانتی‌متر مربع',[('نصف کردن قطر و یافتن شعاع',.25),('فرمول مساحت کره',.25),('جایگذاری و محاسبهٔ ضریب',.25),('پاسخ با π و واحد مربع',.25)],expr=f'4*pi*{r}**2',diagram=solid_svg('sphere'))
 auto(15,1,8,.25,f'مثلث قائم با ضلع‌های قائمه {3*k} و {4*k} را حول ضلع {4*k} دوران می‌دهیم؛ نام حجم حاصل چیست؟','مخروط','0','text',aliases=['مخروط قائم'])
 manual(15,2,8,.75,f'حجم جسم حاصل از دوران مثلث با ضلع‌های قائمهٔ {3*k} و {4*k} حول ضلع {4*k} را با π=3 حساب کن.','شعاع '+str(3*k)+' و ارتفاع '+str(4*k)+' است؛ حجم '+str(36*k**3)+' سانتی‌متر مکعب است.',[('شعاع و ارتفاع متناظر درست',.25),('فرمول و جایگذاری حجم مخروط',.25),('محاسبه و واحد مکعب',.25)],expr=f'3*({3*k})**2*{4*k}/3')
